def fill(text, x, tok):
    for _ in range(3):   # tokens can contain other tokens ($FIELD uses $STROKE)
        for k, v in tok.items():
            text = text.replace('$' + k, v)
    return text.replace('$X', x)


def main():
    for x, tok in SYS.items():
        out = []
        for cid, tpl in T.items():
            block = fill(tpl, x, tok)
            extra = EXTRA.get(x, {}).get(cid)
            if extra:
                block += '\n' + fill(extra, x, tok)
            out.append('/* @c %s */\n%s' % (cid, block))
        open(os.path.join(OUT, 'sys-%s.css' % x), 'w').write('\n'.join(out) + '\n')
        print('sys-%s.css: %d blocks' % (x, len(out)))


if __name__ == '__main__':
    main()
